function sort_third(l){
    const result = new Array(l.length);
    const thirdIndexValues = [];

    // Collect values at indices divisible by three and sort them
    for (let i = 2; i < l.length; i += 3) {
        thirdIndexValues.push(l[i]);
    }
    thirdIndexValues.sort((a, b) => a - b);

    // Copy values from the original array to the result array
    for (let i = 0, j = 0; i < l.length; i++) {
        if (i % 3 === 0) {
            result[i] = l[i];
        } else if (i % 3 === 1) {
            result[i] = l[i];
        } else {
            result[i] = thirdIndexValues[j++];
        }
    }

    return result;
}

