function find_adverbs(text){
  // Split the text into words
  const words = text.split(' ');

  // Initialize an empty array to store adverbs ending with ly and their positions
  const adverbs = [];

  // Iterate through each word in the text
  words.forEach((word, index) => {
    // Check if the word ends with ly
    if (word.endsWith('ly')) {
      // Push the word and its position to the adverbs array
      adverbs.push({ word, position: index });
    }
  });

  // Return the array of adverbs
  return adverbs;
}

