  const n = nums.length;
  for (let i = n - 1; i > 0; i--) {
    let maxIndex = 0;
    for (let j = 1; j <= i; j++) {
      if (nums[j] > nums[maxIndex]) {
        maxIndex = j;
      }
    }
    if (maxIndex !== i) {
      // Flip the array up to the maxIndex
      flip(nums, 0, maxIndex);
      // Flip the array up to i
      flip(nums, 0, i);
    }
  }
  return nums;
}

