function encrypt(s){
    const alphabet = 'abcdefghijklmnopqrstuvwxyz';
    let encrypted = '';

    for (let char of s) {
        if (alphabet.includes(char)) {
            const charIndex = alphabet.indexOf(char);
            const shiftedIndex = (charIndex + (2 * 2) % 26) % 26;
            encrypted += alphabet[shiftedIndex];
        } else {
            encrypted += char;
        }
    }

    return encrypted;
}

