function split_words(txt){
  if (txt.includes(' ')) {
    return txt.split(' ');
  } else if (txt.includes(',')) {
    return txt.split(',');
  } else {
    let count = 0;
    for (let i = 0; i < txt.length; i++) {
      let charCode = txt.charCodeAt(i);
      if (charCode >= 97 && charCode <= 122) {
        let oddOrder = (charCode - 97) % 2 === 0;
        if (!oddOrder) {
          count++;
        }
      }
    }
    return count;
  }
}

