function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = [0, 1];
  for (let i = 2; i <= n; i++) {
    memo[i] = memo[memo[i - 1]] + memo[i - 2];
  }

  return memo[n];
}

function swap_List(newList){
  if (newList.length < 2) {
    return newList;
  }
  const firstElement = newList[0];
  const lastElement = newList[newList.length - 1];
  newList[0] = lastElement;
  newList[newList.length - 1] = firstElement;
  return newList;
}
